#' Matching Estimators
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param adjvars .
#' @param exact .
#' @param estimand .
#' @param k .
#' @param metric .
#' @param biasadj .
#' @param caliper .
#' @param varNn .
#' @param level .
#' @param showMatches .
#' @param showBalance .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uses} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bal} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effects$asDF}
#'
#' \code{as.data.frame(results$effects)}
#'
#' @export
nnmatch <- function(
    data,
    outcome,
    treat,
    covs,
    adjvars,
    exact,
    estimand = "all",
    k = 1,
    metric = "maha",
    biasadj = FALSE,
    caliper = 0,
    varNn = 2,
    level = 95,
    showMatches = TRUE,
    showBalance = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("nnmatch requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(adjvars)) adjvars <- jmvcore::resolveQuo(jmvcore::enquo(adjvars))
    if ( ! missing(exact)) exact <- jmvcore::resolveQuo(jmvcore::enquo(exact))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(adjvars), adjvars, NULL),
            `if`( ! missing(exact), exact, NULL))


    options <- nnmatchOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        adjvars = adjvars,
        exact = exact,
        estimand = estimand,
        k = k,
        metric = metric,
        biasadj = biasadj,
        caliper = caliper,
        varNn = varNn,
        level = level,
        showMatches = showMatches,
        showBalance = showBalance,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- nnmatchClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

